import { getProjectBallotTemplate, type GetProjectBallotTemplateData } from '~/client';

export const useProjectBallotTemplate = defineQuery(() => {
  const route = useRoute('projects-id');
  const projectId = computed(() => route.params.id as string);

  const {
    data: projectBallotTemplate,
    error,
    isLoading,
    refetch,
  } = useQuery({
    key: () => ['project-ballot-template', projectId.value],
    query: () =>
      getProjectBallotTemplate({
        composable: '$fetch',
        path: { project_id: projectId.value },
      }),
    staleTime: 0,
    enabled: () =>
      (useRoute().name === 'projects-id-edit-ballot-template' || useRoute().name === 'projects-id-ballot-template') &&
      !!projectId.value,
  });

  return {
    projectId,
    projectBallotTemplate,
    state: computed(() => projectBallotTemplate.value?.state || null),
    pages: computed(() => projectBallotTemplate.value?.pages || []),
    templateName: computed(() => projectBallotTemplate.value?.name || ''),
    error,
    isLoading,
    refetch,
  };
});
